1	package com.example.starter.compliance.service;
2	
3	import com.example.starter.compliance.ApiException;
4	import com.example.starter.compliance.repo.ClearanceCertificateRow;
5	import com.example.starter.compliance.repo.ComplianceRepository;
6	import com.example.starter.compliance.repo.FilingRow;
7	import com.example.starter.compliance.repo.FormulaAllergenRow;
8	import com.example.starter.compliance.repo.FormulaRow;
9	import com.example.starter.compliance.repo.LineControlRepository;
10	import com.example.starter.compliance.repo.ProductionLineRow;
11	import com.example.starter.compliance.repo.ProductionRecordRow;
12	import com.example.starter.compliance.time.ComplianceClock;
13	import com.example.starter.compliance.web.Requests.ConfirmCertificateRequest;
14	import com.example.starter.compliance.web.Requests.ControlledProductionRequest;
15	import com.example.starter.compliance.web.Requests.FormulaAllergenRequest;
16	import com.example.starter.compliance.web.Requests.RegisterLineRequest;
17	import java.util.ArrayList;
18	import java.util.LinkedHashSet;
19	import java.util.List;
20	import java.util.Set;
21	import java.util.TreeSet;
22	import org.springframework.dao.DuplicateKeyException;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.stereotype.Service;
25	import org.springframework.transaction.annotation.Transactional;
26	
27	/**
28	 * 清线凭证门禁领域服务：
29	 *
30	 * <p>用合成目录为配方版本登记过敏原集合（乐观版本，从 1 开始），为生产线登记最近一次量产版本与
31	 * 递增占用版本（从 1 开始）。受控量产声明线路与当前占用版本：前批含新批未声明的任一过敏原时，
32	 * 必须引用覆盖这些过敏原、在确认后 2 小时内有效（恰满 2 小时失效）、线路与占用版本均匹配的双人
33	 * 确认凭证；其他切换不需凭证。
34	 *
35	 * <p>受理时在同一事务内校验备案仍有效、凭证范围与线路版本，再原子写生产记录、推进占用版本与最近
36	 * 配方、核销并作废旧凭证；任一校验失败整体回滚，不消耗凭证。两笔量产并发时同一线路版本至多一笔
37	 * 成功（行锁 + (line_code, occupied_version) 唯一约束双重保证）。
38	 *
39	 * <p>全部新增写操作以 requestId 幂等：完整参数含版本、集合与精确时刻，同键同参重放首次冻结结果，
40	 * 异参 409，失败不占键。参数非法 400、对象不存在 404、业务拒绝 422。
41	 */
42	@Service
43	public class LineControlService {
44	
45	    /** 凭证有效期：UTC 确认后 2 小时，恰满 2 小时失效。 */
46	    public static final long CERTIFICATE_VALIDITY_MILLIS = 2L * 60L * 60L * 1000L;
47	
48	    private final LineControlRepository lineRepository;
49	    private final ComplianceRepository repository;
50	    private final ComplianceClock clock;
51	    private final IdempotentExecutor idempotency;
52	    private final FilingTransitions transitions;
53	
54	    public LineControlService(LineControlRepository lineRepository,
55	            ComplianceRepository repository, ComplianceClock clock,
56	            IdempotentExecutor idempotency, FilingTransitions transitions) {
57	        this.lineRepository = lineRepository;
58	        this.repository = repository;
59	        this.clock = clock;
60	        this.idempotency = idempotency;
61	        this.transitions = transitions;
62	    }
63	
64	    // ---------------- 配方版本过敏原登记 ----------------
65	
66	    @Transactional
67	    public ServiceResult<LineControlResults.FormulaAllerView> registerFormulaAllergens(
68	            FormulaAllergenRequest request) {
69	        return idempotency.execute(request.requestId(), request,
70	                LineControlResults.FormulaAllerView.class, () -> {
71	                    String productCode = requireText(request.productCode(), "产品编码不能为空");
72	                    if (request.formulaVersion() == null || request.formulaVersion() < 1) {
73	                        throw invalid("配方版本号必须为正整数");
74	                    }
75	                    if (request.expectedVersion() == null || request.expectedVersion() < 0) {
76	                        throw invalid("expectedVersion 不能为空且不能为负（新增传 0）");
77	                    }
78	                    if (request.registeredAt() == null || request.registeredAt() < 0) {
79	                        throw invalid("registeredAt 精确时刻不能为空");
80	                    }
81	                    List<String> allergens = normalizeAllergens(request.allergens());
82	
83	                    long now = clock.nowMillis();
84	                    var existing = lineRepository.findFormulaAllergen(productCode,
85	                            request.formulaVersion());
86	                    if (request.expectedVersion() == 0) {
87	                        if (existing.isPresent()) {
88	                            throw new ApiException(HttpStatus.CONFLICT, "ALLERGEN_VERSION_EXISTS",
89	                                    "该配方版本已登记过敏原集合，修改须携带当前 expectedVersion");
90	                        }
91	                        try {
92	                            lineRepository.insertFormulaAllergen(productCode,
93	                                    request.formulaVersion(), allergens, request.registeredAt(), now);
94	                        } catch (DuplicateKeyException e) {
95	                            // 并发首次登记：唯一 (product_code, formula_version) 冲突，仅一方成功。
96	                            throw new ApiException(HttpStatus.CONFLICT, "ALLERGEN_VERSION_EXISTS",
97	                                    "该配方版本过敏原登记已存在");
98	                        }
99	                    } else {
100	                        FormulaAllergenRow row = existing.orElseThrow(() ->
101	                                notFound("FORMULA_ALLERGEN_NOT_FOUND",
102	                                        "配方版本过敏原登记不存在：" + productCode + "#"
103	                                                + request.formulaVersion()));
104	                        if (row.version() != request.expectedVersion()) {
105	                            throw new ApiException(HttpStatus.CONFLICT,
106	                                    "OPTIMISTIC_VERSION_CONFLICT",
107	                                    "过敏原登记版本已变化：expectedVersion="
108	                                            + request.expectedVersion() + "，当前版本=" + row.version());
109	                        }
110	                        if (!lineRepository.updateFormulaAllergen(row.id(), row.version(), allergens,
111	                                request.registeredAt(), now)) {
112	                            // 并发修改：乐观版本条件失配，整事务回滚，仅一方提交。
113	                            throw new ApiException(HttpStatus.CONFLICT,
114	                                    "OPTIMISTIC_VERSION_CONFLICT", "过敏原登记并发修改冲突");
115	                        }
116	                    }
117	                    FormulaAllergenRow saved = lineRepository.findFormulaAllergen(productCode,
118	                            request.formulaVersion()).orElseThrow();
119	                    return new IdempotentExecutor.Outcome<>(buildAllerView(saved, false),
120	                            HttpStatus.OK.value());
121	                });
122	    }
123	
124	    // ---------------- 生产线登记 ----------------
125	
126	    @Transactional
127	    public ServiceResult<LineControlResults.LineView> registerLine(RegisterLineRequest request) {
128	        return idempotency.execute(request.requestId(), request,
129	                LineControlResults.LineView.class, () -> {
130	                    String lineCode = requireText(request.lineCode(), "生产线编码不能为空");
131	                    requireText(request.lineName(), "生产线名称不能为空");
132	                    if (request.registeredAt() == null || request.registeredAt() < 0) {
133	                        throw invalid("registeredAt 精确时刻不能为空");
134	                    }
135	                    boolean hasProduct = request.lastProductCode() != null
136	                            && !request.lastProductCode().isBlank();
137	                    boolean hasVersion = request.lastFormulaVersion() != null;
138	                    if (hasProduct != hasVersion) {
139	                        throw invalid("最近量产产品与版本必须同时提供或同时留空");
140	                    }
141	                    if (hasVersion && request.lastFormulaVersion() < 1) {
142	                        throw invalid("最近量产配方版本号必须为正整数");
143	                    }
144	                    if (lineRepository.findLine(lineCode).isPresent()) {
145	                        throw new ApiException(HttpStatus.CONFLICT, "LINE_EXISTS",
146	                                "生产线已登记：" + lineCode);
147	                    }
148	                    if (hasProduct
149	                            && lineRepository.findFormulaAllergen(request.lastProductCode(),
150	                                    request.lastFormulaVersion()).isEmpty()) {
151	                        throw new ApiException(HttpStatus.BAD_REQUEST,
152	                                "ALLERGEN_REGISTRATION_REQUIRED",
153	                                "最近量产配方版本尚未登记过敏原集合，无法判定遗留过敏原："
154	                                        + request.lastProductCode() + "#"
155	                                        + request.lastFormulaVersion());
156	                    }
157	                    try {
158	                        lineRepository.insertLine(lineCode, request.lineName(),
159	                                request.registeredAt());
160	                    } catch (DuplicateKeyException e) {
161	                        throw new ApiException(HttpStatus.CONFLICT, "LINE_EXISTS",
162	                                "生产线已登记：" + lineCode);
163	                    }
164	                    if (hasProduct) {
165	                        // 合成登记最近一次量产版本：占用版本固定从 1 开始，最近量产版本直接落列。
166	                        lineRepository.updateLineLastProduction(lineCode,
167	                                request.lastProductCode(), request.lastFormulaVersion());
168	                    }
169	                    ProductionLineRow row = lineRepository.findLine(lineCode).orElseThrow();
170	                    return new IdempotentExecutor.Outcome<>(buildLineView(row, false),
171	                            HttpStatus.OK.value());
172	                });
173	    }
174	
175	    // ---------------- 清线凭证双人确认 ----------------
176	
177	    @Transactional
178	    public ServiceResult<LineControlResults.CertificateView> confirmCertificate(
179	            ConfirmCertificateRequest request) {
180	        return idempotency.execute(request.requestId(), request,
181	                LineControlResults.CertificateView.class, () -> {
182	                    String certificateNo =
183	                            requireText(request.certificateNo(), "凭证编号不能为空");
184	                    String lineCode = requireText(request.lineCode(), "生产线编码不能为空");
185	                    List<String> allergens = normalizeAllergens(request.allergens());
186	                    if (allergens.isEmpty()) {
187	                        throw invalid("清线凭证覆盖的过敏原集合不能为空");
188	                    }
189	                    String operator = requireText(request.operatorCode(), "操作人不能为空");
190	                    String reviewer = requireText(request.reviewerCode(), "复核人不能为空");
191	                    if (operator.equals(reviewer)) {
192	                        throw new ApiException(HttpStatus.BAD_REQUEST,
193	                                "OPERATOR_REVIEWER_SAME",
194	                                "清线凭证必须经操作人、复核人两名不同人员共同确认");
195	                    }
196	                    if (request.clearedAt() == null || request.clearedAt() < 0) {
197	                        throw invalid("clearedAt 清线时刻不能为空");
198	                    }
199	                    if (request.confirmedAt() == null || request.confirmedAt() < 0) {
200	                        throw invalid("confirmedAt 确认时刻不能为空");
201	                    }
202	                    if (request.confirmedAt() < request.clearedAt()) {
203	                        throw invalid("确认时刻不能早于清线时刻");
204	                    }
205	                    if (lineRepository.findCertificateByNo(certificateNo).isPresent()) {
206	                        throw new ApiException(HttpStatus.CONFLICT, "CERTIFICATE_NO_EXISTS",
207	                                "凭证编号已存在：" + certificateNo);
208	                    }
209	                    // 锁线路固定当时占用版本：清线时刻与确认之间若有量产提交，凭证将固定到新占用版本，
210	                    // 旧版本缺口不再可能被该凭证覆盖。
211	                    ProductionLineRow line = lineRepository.findLineForUpdate(lineCode)
212	                            .orElseThrow(() -> notFound("LINE_NOT_FOUND",
213	                                    "生产线不存在：" + lineCode));
214	                    long id;
215	                    try {
216	                        id = lineRepository.insertCertificate(certificateNo, lineCode, allergens,
217	                                operator, reviewer, request.clearedAt(), line.occupiedVersion(),
218	                                request.confirmedAt());
219	                    } catch (DuplicateKeyException e) {
220	                        throw new ApiException(HttpStatus.CONFLICT, "CERTIFICATE_NO_EXISTS",
221	                                "凭证编号已存在：" + certificateNo);
222	                    }
223	                    ClearanceCertificateRow saved =
224	                            lineRepository.findCertificateById(id).orElseThrow();
225	                    return new IdempotentExecutor.Outcome<>(buildCertificateView(saved, false),
226	                            HttpStatus.OK.value());
227	                });
228	    }
229	
230	    // ---------------- 受控量产 ----------------
231	
232	    @Transactional
233	    public ServiceResult<LineControlResults.ControlledProductionView> controlledProduction(
234	            ControlledProductionRequest request) {
235	        return idempotency.execute(request.requestId(), request,
236	                LineControlResults.ControlledProductionView.class, () -> {
237	                    if (request.filingId() == null) {
238	                        throw invalid("filingId 不能为空");
239	                    }
240	                    String lineCode = requireText(request.lineCode(), "生产线编码不能为空");
241	                    if (request.occupiedVersion() == null || request.occupiedVersion() < 1) {
242	                        throw invalid("occupiedVersion 必须为正整数");
243	                    }
244	                    if (request.batchNo() == null || request.batchNo().isBlank()) {
245	                        throw invalid("批次号不能为空");
246	                    }
247	                    if (request.quantityKg() == null || request.quantityKg().signum() < 0) {
248	                        throw invalid("量产数量必须为非负数");
249	                    }
250	                    if (request.reportedAt() == null || request.reportedAt() < 0) {
251	                        throw invalid("reportedAt 精确时刻不能为空");
252	                    }
253	
254	                    // 先锁线路再锁备案：同线路并发量产按唯一提交顺序串行；
255	                    // 暂停/注销与量产竞态时，后提交者基于行锁内最新状态裁决，历史记录不被改写。
256	                    ProductionLineRow line = lineRepository.findLineForUpdate(lineCode)
257	                            .orElseThrow(() -> notFound("LINE_NOT_FOUND",
258	                                    "生产线不存在：" + lineCode));
259	                    FilingRow filing = repository.findFilingByIdForUpdate(request.filingId())
260	                            .orElseThrow(() -> notFound("FILING_NOT_FOUND",
261	                                    "备案不存在：" + request.filingId()));
262	                    rejectIfFilingNotEffective(filing);
263	
264	                    if (line.occupiedVersion() != request.occupiedVersion()) {
265	                        throw new ApiException(HttpStatus.CONFLICT, "LINE_VERSION_CONFLICT",
266	                                "线路占用版本不匹配：声明 " + request.occupiedVersion()
267	                                        + "，当前 " + line.occupiedVersion());
268	                    }
269	
270	                    FormulaRow formula = repository.findFormulaById(filing.formulaId())
271	                            .orElseThrow(() -> notFound("FORMULA_NOT_FOUND",
272	                                    "备案对应配方不存在：" + filing.formulaId()));
273	                    List<String> newAllergens = requireRegisteredAllergens(formula.productCode(),
274	                            formula.version(), "NEW_BATCH_ALLERGEN_NOT_REGISTERED");
275	
276	                    // 前批遗留过敏原 = 最近量产版本过敏原集合 - 新批声明集合。
277	                    Set<String> leftover = new TreeSet<>();
278	                    if (line.lastProductCode() != null) {
279	                        List<String> previousAllergens = requireRegisteredAllergens(
280	                                line.lastProductCode(), line.lastFormulaVersion(),
281	                                "PREVIOUS_BATCH_ALLERGEN_NOT_REGISTERED");
282	                        leftover.addAll(previousAllergens);
283	                        leftover.removeAll(newAllergens);
284	                    }
285	
286	                    Long usedCertificateId = null;
287	                    if (!leftover.isEmpty()) {
288	                        // 前批含新批未声明过敏原：必须引用覆盖全部遗留过敏原的有效凭证。
289	                        ClearanceCertificateRow certificate = requireCertificate(
290	                                request.certificateId(), line, request.occupiedVersion(),
291	                                request.reportedAt(), leftover);
292	                        usedCertificateId = certificate.id();
293	                    }
294	
295	                    long recordId;
296	                    try {
297	                        recordId = repository.insertControlledProductionRecord(filing.id(),
298	                                request.batchNo(), request.quantityKg(), request.reportedAt(),
299	                                lineCode, request.occupiedVersion(), usedCertificateId);
300	                    } catch (DuplicateKeyException e) {
301	                        // 唯一约束兜底：并发同线路同占用版本仅一笔成功，败者不写任何记录。
302	                        throw new ApiException(HttpStatus.CONFLICT, "LINE_VERSION_CONFLICT",
303	                                "同一线路版本已有量产提交，占用版本：" + request.occupiedVersion());
304	                    }
305	                    if (!lineRepository.occupyLine(lineCode, request.occupiedVersion(),
306	                            formula.productCode(), formula.version(), request.reportedAt())) {
307	                        // 行锁内仍失配只会发生在并发推进场景：整事务回滚，凭证不被核销。
308	                        throw new ApiException(HttpStatus.CONFLICT, "LINE_VERSION_CONFLICT",
309	                                "线路占用版本已被并发量产推进：" + lineCode);
310	                    }
311	                    if (usedCertificateId != null
312	                            && !lineRepository.consumeCertificate(usedCertificateId,
313	                                    request.reportedAt())) {
314	                        // 凭证在锁内已失效（理论被并发改写）：回滚整笔量产，禁止无凭证带过敏原切换。
315	                        throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
316	                                "CERTIFICATE_NOT_VALID", "凭证已失效，不能核销");
317	                    }
318	                    // 后续任何生产先提交即作废旧凭证：该线路其余 ACTIVE 凭证一律失效。
319	                    lineRepository.supersedeActiveCertificates(lineCode, request.reportedAt());
320	
321	                    return new IdempotentExecutor.Outcome<>(
322	                            new LineControlResults.ControlledProductionView(recordId, filing.id(),
323	                                    lineCode, request.occupiedVersion(), request.batchNo(),
324	                                    request.quantityKg().stripTrailingZeros().toPlainString(),
325	                                    request.reportedAt(), usedCertificateId, false),
326	                            HttpStatus.OK.value());
327	                });
328	    }
329	
330	    // ---------------- 查询 ----------------
331	
332	    @Transactional(readOnly = true)
333	    public LineControlResults.FormulaAllerView getAllergenRegistration(String productCode,
334	            int formulaVersion) {
335	        FormulaAllergenRow row = lineRepository.findFormulaAllergen(productCode, formulaVersion)
336	                .orElseThrow(() -> notFound("FORMULA_ALLERGEN_NOT_FOUND",
337	                        "配方版本过敏原登记不存在：" + productCode + "#" + formulaVersion));
338	        return buildAllerView(row, false);
339	    }
340	
341	    @Transactional(readOnly = true)
342	    public LineControlResults.LineView getLine(String lineCode) {
343	        ProductionLineRow row = lineRepository.findLine(lineCode)
344	                .orElseThrow(() -> notFound("LINE_NOT_FOUND", "生产线不存在：" + lineCode));
345	        return buildLineView(row, false);
346	    }
347	
348	    @Transactional(readOnly = true)
349	    public LineControlResults.CertificateView getCertificate(long certificateId) {
350	        ClearanceCertificateRow row = lineRepository.findCertificateById(certificateId)
351	                .orElseThrow(() -> notFound("CERTIFICATE_NOT_FOUND",
352	                        "清线凭证不存在：" + certificateId));
353	        return buildCertificateView(row, false);
354	    }
355	
356	    @Transactional(readOnly = true)
357	    public LineControlResults.LineProductionView getLineProductions(String lineCode) {
358	        if (lineRepository.findLine(lineCode).isEmpty()) {
359	            throw notFound("LINE_NOT_FOUND", "生产线不存在：" + lineCode);
360	        }
361	        List<LineControlResults.ControlledProductionView> productions =
362	                repository.findProductionRecordsByLine(lineCode).stream()
363	                        .map(this::buildProductionView)
364	                        .toList();
365	        return new LineControlResults.LineProductionView(lineCode, productions);
366	    }
367	
368	    // ---------------- 内部辅助 ----------------
369	
370	    /** 备案门禁：注销/暂停/复审观察逾期一律拒绝，受控入口不得绕过。 */
371	    private void rejectIfFilingNotEffective(FilingRow filing) {
372	        if ("CANCELLED".equals(filing.status())) {
373	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "FILING_CANCELLED",
374	                    "备案已注销，受控量产拒绝");
375	        }
376	        if ("SUSPENDED".equals(filing.status())) {
377	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "FILING_SUSPENDED",
378	                    "备案已暂停，受控量产拒绝");
379	        }
380	        if ("REVIEW_WATCH".equals(filing.status())
381	                && clock.todayEpochDay() > filing.watchStartDay()
382	                        + ComplianceService.REVIEW_GRACE_DAYS) {
383	            // 逾期未复审：沿用独立事务立即暂停并释放有效位，随后量产整体回滚（失败不占幂等键）。
384	            transitions.suspendOverdueNewTransaction(filing);
385	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "FILING_SUSPENDED",
386	                    "备案复审观察已逾期并自动暂停，受控量产拒绝");
387	        }
388	        if (!"ACTIVE".equals(filing.status()) && !"REVIEW_WATCH".equals(filing.status())) {
389	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "FILING_NOT_EFFECTIVE",
390	                    "备案当前状态不允许量产：" + filing.status());
391	        }
392	    }
393	
394	    private ClearanceCertificateRow requireCertificate(Long certificateId,
395	            ProductionLineRow line, int occupiedVersion, long reportedAt, Set<String> leftover) {
396	        if (certificateId == null) {
397	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
398	                    "CLEARANCE_CERTIFICATE_REQUIRED",
399	                    "前批遗留新批未声明过敏原 " + new ArrayList<>(leftover)
400	                            + "，必须引用有效清线凭证");
401	        }
402	        ClearanceCertificateRow certificate = lineRepository.findCertificateById(certificateId)
403	                .orElseThrow(() -> notFound("CERTIFICATE_NOT_FOUND",
404	                        "清线凭证不存在：" + certificateId));
405	        if (!"ACTIVE".equals(certificate.status())) {
406	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "CERTIFICATE_NOT_VALID",
407	                    "清线凭证已" + ("CONSUMED".equals(certificate.status()) ? "核销" : "作废")
408	                            + "，不能重复使用");
409	        }
410	        if (!certificate.lineCode().equals(line.lineCode())) {
411	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
412	                    "CERTIFICATE_LINE_MISMATCH",
413	                    "凭证线路不匹配：凭证 " + certificate.lineCode() + "，量产线路 "
414	                            + line.lineCode());
415	        }
416	        if (certificate.occupiedVersion() != occupiedVersion) {
417	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
418	                    "CERTIFICATE_VERSION_MISMATCH",
419	                    "凭证固定占用版本 " + certificate.occupiedVersion() + " 与当前占用版本 "
420	                            + occupiedVersion + " 不匹配");
421	        }
422	        long expiresAt = certificate.confirmedAt() + CERTIFICATE_VALIDITY_MILLIS;
423	        if (reportedAt < certificate.confirmedAt()) {
424	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "CERTIFICATE_NOT_VALID",
425	                    "量产时刻早于凭证确认时刻");
426	        }
427	        if (reportedAt >= expiresAt) {
428	            // 恰满 2 小时失效。
429	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "CERTIFICATE_EXPIRED",
430	                    "清线凭证已超过确认后 2 小时有效期（恰满 2 小时失效）");
431	        }
432	        Set<String> uncovered = new TreeSet<>(leftover);
433	        uncovered.removeAll(certificate.clearedAllergens());
434	        if (!uncovered.isEmpty()) {
435	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
436	                    "CERTIFICATE_COVERAGE_INSUFFICIENT",
437	                    "凭证未覆盖全部遗留过敏原，缺少：" + new ArrayList<>(uncovered));
438	        }
439	        return certificate;
440	    }
441	
442	    private List<String> requireRegisteredAllergens(String productCode, Integer formulaVersion,
443	            String errorCode) {
444	        FormulaAllergenRow row = lineRepository.findFormulaAllergen(productCode, formulaVersion)
445	                .orElseThrow(() -> new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, errorCode,
446	                        "配方版本尚未登记过敏原集合：" + productCode + "#" + formulaVersion));
447	        return row.allergens();
448	    }
449	
450	    /** 规范化过敏原集合：去空白、去重、按编码字典序排列，并校验合成目录存在。 */
451	    private List<String> normalizeAllergens(List<String> allergens) {
452	        if (allergens == null) {
453	            throw invalid("过敏原集合不能为空");
454	        }
455	        Set<String> normalized = new LinkedHashSet<>();
456	        for (String code : allergens) {
457	            if (code == null || code.isBlank()) {
458	                throw invalid("过敏原编码不能为空");
459	            }
460	            String trimmed = code.trim();
461	            if (!lineRepository.allergenExists(trimmed)) {
462	                throw new ApiException(HttpStatus.BAD_REQUEST, "ALLERGEN_NOT_FOUND",
463	                        "过敏原合成目录中不存在：" + trimmed);
464	            }
465	            normalized.add(trimmed);
466	        }
467	        return List.copyOf(new TreeSet<>(normalized));
468	    }
469	
470	    private static String requireText(String value, String message) {
471	        if (value == null || value.isBlank()) {
472	            throw invalid(message);
473	        }
474	        return value.trim();
475	    }
476	
477	    private static ApiException invalid(String message) {
478	        return new ApiException(HttpStatus.BAD_REQUEST, "INVALID_PARAM", message);
479	    }
480	
481	    private static ApiException notFound(String code, String message) {
482	        return new ApiException(HttpStatus.NOT_FOUND, code, message);
483	    }
484	
485	    private static LineControlResults.FormulaAllerView buildAllerView(FormulaAllergenRow row,
486	            boolean replayed) {
487	        return new LineControlResults.FormulaAllerView(row.id(), row.productCode(),
488	                row.formulaVersion(), List.copyOf(row.allergens()), row.version(),
489	                row.registeredAt(), replayed);
490	    }
491	
492	    private static LineControlResults.LineView buildLineView(ProductionLineRow row,
493	            boolean replayed) {
494	        return new LineControlResults.LineView(row.lineCode(), row.lineName(),
495	                row.lastProductCode(), row.lastFormulaVersion(), row.occupiedVersion(),
496	                row.updatedAt(), replayed);
497	    }
498	
499	    private static LineControlResults.CertificateView buildCertificateView(
500	            ClearanceCertificateRow row, boolean replayed) {
501	        return new LineControlResults.CertificateView(row.id(), row.certificateNo(),
502	                row.lineCode(), List.copyOf(row.clearedAllergens()), row.operatorCode(),
503	                row.reviewerCode(), row.clearedAt(), row.occupiedVersion(), row.status(),
504	                row.confirmedAt(), row.confirmedAt() + CERTIFICATE_VALIDITY_MILLIS,
505	                row.consumedAt(), replayed);
506	    }
507	
508	    private LineControlResults.ControlledProductionView buildProductionView(
509	            ProductionRecordRow row) {
510	        return new LineControlResults.ControlledProductionView(row.id(), row.filingId(),
511	                row.lineCode(), row.occupiedVersion(), row.batchNo(),
512	                row.quantityKg().stripTrailingZeros().toPlainString(), row.reportedAt(),
513	                row.clearanceCertificateId(), false);
514	    }
515	}
