1	package com.example.starter.compliance.service;
2	
3	import com.example.starter.compliance.ApiException;
4	import com.example.starter.compliance.repo.ComplianceRepository;
5	import com.example.starter.compliance.repo.IdempotentRow;
6	import com.example.starter.compliance.support.JsonSupport;
7	import com.example.starter.compliance.time.ComplianceClock;
8	import java.nio.charset.StandardCharsets;
9	import java.security.MessageDigest;
10	import java.security.NoSuchAlgorithmException;
11	import java.util.HexFormat;
12	import java.util.LinkedHashMap;
13	import java.util.Map;
14	import java.util.Optional;
15	import java.util.function.Supplier;
16	import org.springframework.dao.DuplicateKeyException;
17	import org.springframework.http.HttpStatus;
18	import org.springframework.stereotype.Component;
19	
20	/**
21	 * requestId 幂等执行器（业务、版本与幂等结果同事务）：
22	 * 指纹覆盖 requestId 与全部业务字段，先插入占位行（status_code=0）抢占 requestId，
23	 * 执行业务动作后回填首次响应；同键同参返回首次结果（含首次状态码），
24	 * 同键异参返回 409；业务动作抛错时由外层事务回滚，占位行一并回滚，失败不占键。
25	 *
26	 * <p>调用方方法必须为 {@code @Transactional}，保证占位行、业务写入与结果回填同提交同回滚。
27	 */
28	@Component
29	public class IdempotentExecutor {
30	
31	    private final ComplianceRepository repository;
32	    private final ComplianceClock clock;
33	
34	    public IdempotentExecutor(ComplianceRepository repository, ComplianceClock clock) {
35	        this.repository = repository;
36	        this.clock = clock;
37	    }
38	
39	    /** 业务动作结果：响应体 + 首次 HTTP 状态码。 */
40	    public record Outcome<T>(T body, int status) {
41	    }
42	
43	    public <T> ServiceResult<T> execute(String requestId, Object params, Class<T> type,
44	            Supplier<Outcome<T>> action) {
45	        if (requestId == null || requestId.isBlank()) {
46	            throw new ApiException(HttpStatus.BAD_REQUEST, "REQUEST_ID_REQUIRED",
47	                    "变更接口必须提供 requestId");
48	        }
49	        String fingerprint = fingerprint(requestId, params);
50	        Optional<IdempotentRow> existing = repository.findIdempotent(requestId);
51	        if (existing.isPresent()) {
52	            return resolve(existing.get(), fingerprint, type);
53	        }
54	        try {
55	            repository.insertIdempotent(requestId, fingerprint, 0, null, clock.nowMillis());
56	        } catch (DuplicateKeyException e) {
57	            // 并发同键：另一事务已占位或已完成，按其记录重放或报 409。
58	            IdempotentRow raced = repository.findIdempotent(requestId)
59	                    .orElseThrow(() -> new ApiException(HttpStatus.CONFLICT,
60	                            "REQUEST_IN_PROGRESS", "同一 requestId 正在处理中"));
61	            return resolve(raced, fingerprint, type);
62	        }
63	
64	        Outcome<T> outcome = action.get();
65	        repository.completeIdempotent(requestId, outcome.status(),
66	                JsonSupport.write(outcome.body()));
67	        return new ServiceResult<>(outcome.body(), false, outcome.status());
68	    }
69	
70	    private <T> ServiceResult<T> resolve(IdempotentRow row, String fingerprint, Class<T> type) {
71	        if (!row.fingerprint().equals(fingerprint)) {
72	            throw new ApiException(HttpStatus.CONFLICT, "REQUEST_PARAM_CONFLICT",
73	                    "requestId 已用于不同业务参数");
74	        }
75	        if (row.statusCode() == 0 || row.responseJson() == null) {
76	            throw new ApiException(HttpStatus.CONFLICT, "REQUEST_IN_PROGRESS",
77	                    "同一 requestId 的请求正在处理中");
78	        }
79	        return ServiceResult.replay(JsonSupport.readReplayed(row.responseJson(), type),
80	                row.statusCode());
81	    }
82	
83	    /**
84	     * 结构化指纹：规范化 JSON 递归按字段名排序、集合保持有序序列，
85	     * 使合法文本即使包含分隔符（如逗号、竖线）也不会与多值集合混淆。
86	     */
87	    public static String fingerprint(String requestId, Object params) {
88	        Map<String, Object> material = new LinkedHashMap<>();
89	        material.put("requestId", requestId);
90	        material.put("params", params);
91	        String canonical = JsonSupport.canonical(material);
92	        try {
93	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
94	            byte[] hash = digest.digest(canonical.getBytes(StandardCharsets.UTF_8));
95	            return HexFormat.of().formatHex(hash);
96	        } catch (NoSuchAlgorithmException e) {
97	            throw new IllegalStateException(e);
98	        }
99	    }
100	}
