2	
3	import com.example.starter.compliance.repo.ComplianceRepository;
4	import com.example.starter.compliance.repo.LineControlRepository;
5	import java.math.BigDecimal;
6	import org.springframework.boot.ApplicationArguments;
7	import org.springframework.boot.ApplicationRunner;
8	import org.springframework.core.annotation.Order;
9	import org.springframework.stereotype.Component;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	/**
13	 * 合成基础数据初始化（幂等执行，仅写入目录与初始限量，不写入任何配方/备案业务数据）：
14	 * <ul>
15	 *   <li>食品分类：BEV01 风味饮料、BAK01 糕点、MEAT01 熟肉制品；</li>
16	 *   <li>添加剂：E202 山梨酸钾/防腐剂、E211 苯甲酸钠/防腐剂、E102 柠檬黄/着色剂、
17	 *       E129 诱惑红/着色剂、E300 抗坏血酸/抗氧化剂；</li>
18	 *   <li>复合配料：ING_SAUCE 复合调味酱（含 E202 2.0 g/kg、E211 4.0 g/kg）、
19	 *       ING_SYRUP 果味糖浆（含 E102 0.5 g/kg）；</li>
20	 *   <li>过敏原（合成清线目录）：ALG_MILK 乳、ALG_EGG 蛋、ALG_PEANUT 花生、
21	 *       ALG_SOY 大豆、ALG_WHEAT 小麦、ALG_FISH 鱼；</li>
22	 *   <li>初始限量（g/kg 终产品）：BEV01 下 E202=0.5、E211=1.0、E102=0.1、E129=0.1、E300=0.5；
23	 *       BAK01 下 E202=1.0、E211=1.0、E300=2.0；MEAT01 下 E202=1.5、E300=0.5。</li>
24	 * </ul>
25	 */
26	@Component
27	@Order(0)
28	public class SyntheticDataInitializer implements ApplicationRunner {
29	
30	    private final ComplianceRepository repository;
31	    private final LineControlRepository lineRepository;
32	
33	    public SyntheticDataInitializer(ComplianceRepository repository,
34	            LineControlRepository lineRepository) {
35	        this.repository = repository;
36	        this.lineRepository = lineRepository;
37	    }
38	
39	    @Override
40	    @Transactional
41	    public void run(ApplicationArguments args) {
42	        if (repository.countCategories() > 0) {
43	            return;
44	        }
45	
