280	        ControlledProductionRequest unregistered = Fixtures.controlled(Fixtures.requestId(),
281	                filingActive, "L-F", 1, "B-U", "1", null, t0 + 1);
282	        assertThatRejected(unregistered, "NEW_BATCH_ALLERGEN_NOT_REGISTERED");
283	        // 失败未推进版本。
284	        assertThat(lineService.getLine("L-F").occupiedVersion()).isEqualTo(1);
285	    }
286	
287	    @Test
288	    void notFoundAndInvalidParamsMapTo404And400() {
289	        ControlledProductionRequest missingFiling = Fixtures.controlled(Fixtures.requestId(),
290	                999_999L, "L-GHOST", 1, "B", "1", null, 1_800_000_000_000L);
291	        assertThatThrownBy(() -> lineService.controlledProduction(missingFiling))
292	                .isInstanceOf(ApiException.class)
293	                .satisfies(ex -> assertThat(((ApiException) ex).getStatus())
294	                        .isEqualTo(HttpStatus.NOT_FOUND));
295	
296	        lineService.registerLine(freshLine("L-GHOST", null, null, 1_800_000_000_000L));
297	        ControlledProductionRequest badVersion = Fixtures.controlled(Fixtures.requestId(),
298	                999_999L, "L-GHOST", 0, "B", "1", null, 1_800_000_000_000L);
299	        assertThatThrownBy(() -> lineService.controlledProduction(badVersion))
300	                .isInstanceOf(ApiException.class)
301	                .satisfies(ex -> assertThat(((ApiException) ex).getStatus())
302	                        .isEqualTo(HttpStatus.BAD_REQUEST));
303	
304	        assertThatThrownBy(() -> lineService.getLine("L-UNKNOWN"))
305	                .isInstanceOf(ApiException.class)
306	                .satisfies(ex -> assertThat(((ApiException) ex).getStatus())
307	                        .isEqualTo(HttpStatus.NOT_FOUND));
308	    }
309	
310	    @Test
311	    void idempotentReplayFreezesResultAndDifferentParamsConflict() {
312	        long t0 = 1_800_000_000_000L;
313	        long filingV2 = approvedFiling("P-ID2", 1);
314	        registerAllergens(Fixtures.requestId(), "P-ID1", 1, List.of(MILK), 0, t0);
315	        registerAllergens(Fixtures.requestId(), "P-ID2", 1, List.of(EGG), 0, t0);
316	        lineService.registerLine(freshLine("L-IDEM", "P-ID1", 1, t0));
317	        long certId = lineService.confirmCertificate(certificate("L-IDEM", List.of(MILK),
318	                t0, t0 + 1)).body().certificateId();
319	
320	        ControlledProductionRequest request = Fixtures.controlled("req-controlled-1", filingV2,
321	                "L-IDEM", 1, "B-IDEM", "8", certId, t0 + 2);
322	        ServiceResult<LineControlResults.ControlledProductionView> first =
323	                lineService.controlledProduction(request);
324	        ServiceResult<LineControlResults.ControlledProductionView> replay =
325	                lineService.controlledProduction(request);
326	        assertThat(first.replayed()).isFalse();
327	        assertThat(replay.replayed()).isTrue();
328	        assertThat(replay.body().productionRecordId())
329	                .isEqualTo(first.body().productionRecordId());
330	        // 重放不产生第二条记录、不二次推进版本。
331	        assertThat(lineService.getLine("L-IDEM").occupiedVersion()).isEqualTo(2);
332	        assertThat(lineService.getLineProductions("L-IDEM").productions()).hasSize(1);
333	
334	        // 同键异参（改批次号）：409。
335	        ControlledProductionRequest different = Fixtures.controlled("req-controlled-1", filingV2,
336	                "L-IDEM", 1, "B-OTHER", "8", certId, t0 + 2);
337	        assertThatThrownBy(() -> lineService.controlledProduction(different))
338	                .isInstanceOf(ApiException.class)
339	                .satisfies(ex -> {
340	                    ApiException api = (ApiException) ex;
341	                    assertThat(api.getStatus()).isEqualTo(HttpStatus.CONFLICT);
342	                    assertThat(api.getCode()).isEqualTo("REQUEST_PARAM_CONFLICT");
343	                });
344	
345	        // 业务失败不占键：同一 requestId 先以错误占用版本失败（409，事务回滚），修正后可成功。
346	        String retryableKey = "req-controlled-retry";
347	        registerAllergens(Fixtures.requestId(), "P-ID3", 1, List.of(EGG), 0, t0);
348	        long filingId3 = approvedFiling("P-ID3", 1);
349	        ControlledProductionRequest badFirst = Fixtures.controlled(retryableKey, filingId3,
350	                "L-IDEM", 1, "B-R1", "8", null, t0 + 3);
351	        assertThatThrownBy(() -> lineService.controlledProduction(badFirst))
352	                .isInstanceOf(ApiException.class)
353	                .satisfies(ex -> assertThat(((ApiException) ex).getCode())
354	                        .isEqualTo("LINE_VERSION_CONFLICT"));
355	        ControlledProductionRequest corrected = Fixtures.controlled(retryableKey, filingId3,
356	                "L-IDEM", 2, "B-R1", "8", null, t0 + 3);
357	        ServiceResult<LineControlResults.ControlledProductionView> retried =
358	                lineService.controlledProduction(corrected);
359	        assertThat(retried.replayed()).isFalse();
360	        assertThat(lineService.getLine("L-IDEM").occupiedVersion()).isEqualTo(3);
361	    }
