363	    private void assertThatRejected(ControlledProductionRequest request, String code) {
364	        assertThatThrownBy(() -> lineService.controlledProduction(request))
365	                .isInstanceOf(ApiException.class)
366	                .satisfies(ex -> {
367	                    ApiException api = (ApiException) ex;
368	                    assertThat(api.getStatus()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
369	                    assertThat(api.getCode()).isEqualTo(code);
370	                });
371	    }
